    if n==4:
        c=item['courseBoundConditionalExtension']['wholeConditionalCase']
        briefs.append({'id':'ecology20b-04-by-ea-lotka-volterra-extension','taskDemandDe':'Nur im tatsächlich belegten BY13-EA-Quellenteil4.1, keine gemeinsame GK-Pflicht: '+c['material']['de']+' '+c['task']['de'],'taskDemandEn':'Only under the actually supported BY13 EA source passage4.1, no common basic-course obligation: '+c['material']['en']+' '+c['task']['en'],'expectedPerformanceDe':c['modelAnswer']['de'],'expectedPerformanceEn':c['modelAnswer']['en'],'understandingFocusDe':'Kursbedingte Lotka-Volterra-Erweiterung: vier Terme, positives Gleichgewicht, phasenverschobene Räuber/Beute und idealisierte Modellgrenzen. Die beiden gemeinsamen Modellfälle bleiben separat vollständig.','understandingFocusEn':'Course-bound Lotka-Volterra extension: four terms, positive equilibrium, phase-lagged predators/prey and idealized limitations. Both shared model cases remain separately complete.'})
    dissent=['E1/G1-Autorkandidat mit eigenen Modellmaterialien; keine reale Lernendenleistung, E2, menschliche Prüfung, Freigabe oder Erprobung. Tatsächliche finale Rasterbindungen und zwei unabhängige aktuelle D/P/V-Prüfungen stehen aus.',plan['sourceBoundary']]
