    profile={'archetype':archetype,'expectations':ex,'coverageExpectations':{'requiredExpectationIds':[e['id'] for e in ex],'alternativeExpectationGroups':[],'minimumIndependentDemonstrations':2,'freshVariationRequired':True,'independentTransferRequired':True},'variationAxes':[{'id':f'ecology20b-{n:02d}-context-and-mechanism','textDe':variation[0],'textEn':variation[1]}],'applicationCaseBriefs':briefs}
    candidates['goals'].append({'goalId':item['goalId'],'reason':'Ganze unveränderte aktuelle DE/EN-Zielbeschreibung mit zwei vollständigen unterschiedlichen Material-/Musterfällen operationalisiert. Kandidat für gezielte unabhängige wissenschaftliche Prüfung, keine Freigabe; konkrete offene Quellenfacetten werden ausdrücklich nicht als Abschluss gezählt.','evidenceLevel':'E1','maximumClaimScope':'G1','dissent':dissent,'profile':profile})
